export function cx(...parts: (string | false | null | undefined)[]): string {
  return parts.filter(Boolean).join(' ')
}

export const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

export const pct = (x: number, digits = 1) => `${(x * 100).toFixed(digits)}%`

export function formatHours(h: number): string {
  return h < 1 ? `${Math.round(h * 60)}m` : `${h.toFixed(1)}h`
}

export function formatWhen(iso: string): string {
  const d = new Date(iso)
  return Number.isNaN(d.getTime()) ? iso : d.toISOString().replace('T', ' ').slice(0, 16) + 'Z'
}

// Small scale and format helpers shared by the chart-like components. No dependencies.

export type Scale = ((v: number) => number) & { invert: (px: number) => number; domain: [number, number]; range: [number, number] }

export function linear(domain: [number, number], range: [number, number]): Scale {
  const [d0, d1] = domain
  const [r0, r1] = range
  const span = d1 - d0 || 1
  const f = ((v: number) => r0 + ((v - d0) / span) * (r1 - r0)) as Scale
  f.invert = (px: number) => d0 + ((px - r0) / (r1 - r0 || 1)) * span
  f.domain = domain
  f.range = range
  return f
}

/** Round tick values that fit in [min, max], about `count` of them (1, 2, 5 times a power of ten). */
export function niceTicks(min: number, max: number, count = 6): number[] {
  if (!(max > min)) return [min]
  const raw = (max - min) / Math.max(count, 1)
  const pow = Math.pow(10, Math.floor(Math.log10(raw)))
  const err = raw / pow
  const step = (err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1) * pow
  const out: number[] = []
  for (let v = Math.ceil(min / step) * step; v <= max + step * 1e-9; v += step) out.push(Math.round(v / step) * step)
  return out
}

/** 850 ms, 1.20 s, 2 m 05 s. */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms)) return ''
  if (ms === 0) return '0'
  const abs = Math.abs(ms)
  if (abs < 1) return `${(ms * 1000).toFixed(0)} µs`
  if (abs < 1000) return `${Number(ms.toFixed(abs < 10 ? 1 : 0))} ms`
  if (abs < 60_000) return `${(ms / 1000).toFixed(abs < 10_000 ? 2 : 1)} s`
  const sign = ms < 0 ? '-' : ''
  if (abs >= 86_400_000) return `${sign}${Math.floor(abs / 86_400_000)} d ${Math.floor((abs % 86_400_000) / 3_600_000)} h`
  if (abs >= 3_600_000) return `${sign}${Math.floor(abs / 3_600_000)} h ${String(Math.round((abs % 3_600_000) / 60_000)).padStart(2, '0')} m`
  const m = Math.floor(abs / 60_000)
  const s = Math.round((abs % 60_000) / 1000)
  return `${ms < 0 ? '-' : ''}${m} m ${String(s).padStart(2, '0')} s`
}

export const formatCount = (n: number) => new Intl.NumberFormat('en', { notation: n >= 100_000 ? 'compact' : 'standard', maximumFractionDigits: 1 }).format(n)
export const formatUsd = (n: number) => (n < 0.01 && n > 0 ? '<$0.01' : new Intl.NumberFormat('en', { style: 'currency', currency: 'USD' }).format(n))

/** Cycles through the categorical palette defined as --ol-c1..8 in styles.css. */
export const swatch = (i: number) => `var(--ol-c${(((i % 8) + 8) % 8) + 1})`

export const clampNum = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

import { useEffect, useRef, useState, type RefObject } from 'react'

/** Width of an element, kept current with ResizeObserver. Returns `initial` on the server and before first measure. */
export function useWidth<T extends HTMLElement>(initial = 720): [RefObject<T | null>, number] {
  const ref = useRef<T | null>(null)
  const [width, setWidth] = useState(initial)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    const measure = () => setWidth(Math.max(240, Math.round(el.getBoundingClientRect().width)))
    measure()
    if (typeof ResizeObserver === 'undefined') return
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    return () => ro.disconnect()
  }, [])
  return [ref, width]
}

/** Copies text and reports success briefly. Safe when the clipboard is unavailable. */
export function useCopy(): [boolean, (text: string) => void] {
  const [done, setDone] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  return [
    done,
    (text) => {
      navigator.clipboard?.writeText(text).then(() => {
        setDone(true)
        clearTimeout(timer.current)
        timer.current = setTimeout(() => setDone(false), 1400)
      }, () => undefined)
    },
  ]
}

/** Small inline marks, so no component depends on emoji or symbol fonts. They inherit the current colour. */
const base = { width: 14, height: 14, viewBox: '0 0 14 14', fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': true, focusable: false } as const

export const Check = () => <svg {...base} className="ol-icon"><path d="M2.5 7.5 5.6 10.5 11.5 3.8" /></svg>
export const Cross = () => <svg {...base} className="ol-icon"><path d="M3.5 3.5 10.5 10.5M10.5 3.5 3.5 10.5" /></svg>
export const Lock = ({ open }: { open?: boolean }) => (
  <svg {...base} className="ol-icon"><rect x="2.6" y="6.2" width="8.8" height="6" rx="1.4" />{open ? <path d="M4.6 6.2V4.4a2.4 2.4 0 0 1 4.6-.9" /> : <path d="M4.6 6.2V4.4a2.4 2.4 0 0 1 4.8 0v1.8" />}</svg>
)
export const Fit = () => <svg {...base} className="ol-icon"><path d="M2 5V2h3M9 2h3v3M12 9v3H9M5 12H2V9" /></svg>

// Exact binomial machinery in log space, stable for n in the thousands. Ported from the failure calculus
// so a client statistician can audit it in one file.

const logFactCache: number[] = [0, 0]
function logFact(n: number): number {
  for (let i = logFactCache.length; i <= n; i++) logFactCache[i] = (logFactCache[i - 1] ?? 0) + Math.log(i)
  return logFactCache[n] ?? 0
}
const logChoose = (n: number, k: number) => logFact(n) - logFact(k) - logFact(n - k)

function binomPmf(k: number, n: number, p: number): number {
  if (p <= 0) return k === 0 ? 1 : 0
  if (p >= 1) return k === n ? 1 : 0
  return Math.exp(logChoose(n, k) + k * Math.log(p) + (n - k) * Math.log(1 - p))
}
function binomCdf(k: number, n: number, p: number): number {
  let s = 0
  for (let i = 0; i <= k; i++) s += binomPmf(i, n, p)
  return Math.min(1, s)
}
const binomTailGE = (k: number, n: number, p: number) => (k <= 0 ? 1 : 1 - binomCdf(k - 1, n, p))

export type Interval = { lower: number; upper: number }

/** Clopper-Pearson exact interval for passes out of n, found by bisection on the binomial CDF. */
export function clopperPearson(passes: number, n: number, confidence = 0.95): Interval {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  if (!Number.isInteger(passes) || passes < 0 || passes > n) throw new RangeError('passes must be an integer from 0 to n')
  const alpha = 1 - confidence
  const bisect = (isLow: (p: number) => boolean) => {
    let lo = 0
    let hi = 1
    for (let i = 0; i < 100; i++) {
      const mid = (lo + hi) / 2
      if (isLow(mid)) lo = mid
      else hi = mid
    }
    return (lo + hi) / 2
  }
  const lower = passes === 0 ? 0 : bisect((p) => binomTailGE(passes, n, p) <= alpha / 2)
  const upper = passes === n ? 1 : bisect((p) => binomCdf(passes, n, p) > alpha / 2)
  return { lower, upper }
}

/** Upper bound on the true failure rate when zero failures were seen in n cases: 1 - alpha^(1/n). */
export function zeroFailureUpperBound(n: number, confidence = 0.95): number {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  return 1 - Math.pow(1 - confidence, 1 / n)
}

/**
 * Exact McNemar p-value (two-sided) for a paired re-test on the same case set. Under no change, the cases
 * that flipped split Binomial(regressed + improved, 0.5).
 */
export function mcnemarExact(regressed: number, improved: number): number {
  if (![regressed, improved].every((x) => Number.isInteger(x) && x >= 0)) throw new RangeError('counts must be non-negative integers')
  const n = regressed + improved
  if (n === 0) return 1
  return Math.min(1, 2 * binomCdf(Math.min(regressed, improved), n, 0.5))
}

/* orlune: plain CSS, no Tailwind. Theme by overriding the --ol-* variables, or inherit a shadcn theme:
   --background, --foreground, --muted-foreground, --border and --primary are read when present. */
.ol {
  --ol-bg: var(--background, #ffffff);
  --ol-fg: var(--foreground, #16181d);
  --ol-muted: var(--muted-foreground, #5d6470);
  --ol-line: var(--border, #e3e5ea);
  --ol-accent: var(--primary, #1d232b);
  --ol-surface: color-mix(in srgb, var(--ol-fg) 4%, var(--ol-bg));
  --ol-good: #1b7249;
  --ol-warn: #8f4f00;
  --ol-bad: #b3261e;
  --ol-radius: 10px;
  --ol-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--ol-fg);
  background: var(--ol-bg);
  border: 1px solid var(--ol-line);
  border-radius: var(--ol-radius);
  padding: 16px;
  font: 14px/1.45 system-ui, -apple-system, 'Segoe UI', sans-serif;
  box-sizing: border-box;
}
/* Dark theme: follows the OS unless data-theme says otherwise. The host's shadcn variables win when present;
   the fallbacks keep every pair readable when the host defines none. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) .ol { --ol-bg: var(--background, #0e1115); --ol-fg: var(--foreground, #ececec); --ol-muted: var(--muted-foreground, #9aa1ab); --ol-line: var(--border, #2a3038); --ol-accent: var(--primary, #e7b65c); --ol-good: #5fcf94; --ol-warn: #f0a85a; --ol-bad: #ff8a80; --ol-c1: #6ea0ff; --ol-c2: #f0a85a; --ol-c3: #5fcf94; --ol-c4: #b896f0; --ol-c5: #f27f9a; --ol-c6: #5ccbdc; --ol-c7: #d8c35a; --ol-c8: #9aa1ab; --ol-on-c: #0e1115; }
}
:root[data-theme='dark'] .ol { --ol-bg: var(--background, #0e1115); --ol-fg: var(--foreground, #ececec); --ol-muted: var(--muted-foreground, #9aa1ab); --ol-line: var(--border, #2a3038); --ol-accent: var(--primary, #e7b65c); --ol-good: #5fcf94; --ol-warn: #f0a85a; --ol-bad: #ff8a80; --ol-c1: #6ea0ff; --ol-c2: #f0a85a; --ol-c3: #5fcf94; --ol-c4: #b896f0; --ol-c5: #f27f9a; --ol-c6: #5ccbdc; --ol-c7: #d8c35a; --ol-c8: #9aa1ab; --ol-on-c: #0e1115; }
.ol *, .ol *::before, .ol *::after { box-sizing: border-box; }
.ol-title { margin: 0 0 12px; font-size: 15px; font-weight: 600; }
.ol-sub { color: var(--ol-muted); font-size: 12px; }
.ol-mono { font-variant-numeric: tabular-nums; }
.ol-id { font-family: var(--ol-mono); font-size: 0.92em; }
.ol-list { list-style: none; margin: 0; padding: 0; }
.ol-pill { display: inline-flex; align-items: center; gap: 4px; padding: 1px 9px; border-radius: 999px; font-size: 12.5px; font-weight: 500; background: var(--ol-surface); color: var(--ol-muted); white-space: nowrap; }
.ol-pill[data-tone='good'] { color: var(--ol-good); background: color-mix(in srgb, var(--ol-good) 13%, var(--ol-bg)); }
.ol-pill[data-tone='warn'] { color: var(--ol-warn); background: color-mix(in srgb, var(--ol-warn) 14%, var(--ol-bg)); }
.ol-pill[data-tone='bad'] { color: var(--ol-bad); background: color-mix(in srgb, var(--ol-bad) 12%, var(--ol-bg)); }

/* Swimlane */
.ol-lane { display: grid; grid-template-columns: 110px 1fr; gap: 12px; padding: 8px 0; border-top: 1px solid var(--ol-line); }
.ol-lane:first-of-type { border-top: 0; }
.ol-lane-owner { font-weight: 600; font-size: 13px; }
.ol-steps { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.ol-step { padding: 4px 10px; border-radius: 6px; border: 1px solid var(--ol-line); background: var(--ol-surface); }
.ol-step[data-waiting='true'] { border-color: var(--ol-warn); color: var(--ol-warn); }
.ol-arrow { color: var(--ol-muted); }

/* Trail */
.ol-stop { position: relative; display: grid; grid-template-columns: 20px 1fr auto; gap: 10px; padding-bottom: 14px; }
.ol-stop::before { content: ''; position: absolute; left: 4px; top: 14px; bottom: 0; width: 1px; background: var(--ol-line); }
.ol-stop:last-child::before { display: none; }
.ol-dot { width: 9px; height: 9px; margin-top: 5px; border-radius: 50%; background: var(--ol-accent); }
.ol-dot[data-wait='true'] { background: var(--ol-warn); }

/* Bars (Bottlenecks, Funnel) */
.ol-row { display: grid; grid-template-columns: minmax(80px, 160px) 1fr auto; gap: 10px; align-items: center; padding: 4px 0; }
.ol-bar { height: 10px; border-radius: 5px; background: var(--ol-surface); overflow: hidden; }
.ol-bar > span { display: block; height: 100%; background: var(--ol-accent); border-radius: 5px; }
.ol-bar > span[data-top='true'] { background: var(--ol-warn); }
.ol-kept { margin: 0 0 0 4px; font-size: 12px; color: var(--ol-muted); }

/* Priority */
.ol-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ol-cell { border: 1px solid var(--ol-line); border-radius: 8px; padding: 10px; min-height: 84px; background: var(--ol-surface); }
.ol-cell h4 { margin: 0 0 6px; font-size: 12.5px; font-weight: 500; color: var(--ol-muted); }
.ol-cell ul { margin: 0; padding-left: 16px; }

/* Compare */
.ol-compare { display: grid; grid-template-columns: 120px 1fr 1fr; gap: 0; border: 1px solid var(--ol-line); border-radius: 8px; overflow: hidden; }
.ol-compare [role='columnheader'], .ol-compare [role='rowheader'], .ol-compare [role='cell'] { padding: 8px 10px; border-top: 1px solid var(--ol-line); }
.ol-compare [role='columnheader'] { border-top: 0; background: var(--ol-surface); font-weight: 600; font-size: 12px; }
.ol-compare [role='rowheader'] { color: var(--ol-muted); }

/* Records */
.ol-head-row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 12px; margin-bottom: 8px; }
.ol-dl { display: grid; grid-template-columns: max-content 1fr; gap: 4px 12px; margin: 8px 0 0; }
.ol-dl dt { color: var(--ol-muted); }
.ol-dl dd { margin: 0; }
.ol-verdict { display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 600; }
.ol-verdict[data-ok='true'] { color: var(--ol-good); }
.ol-verdict[data-ok='false'] { color: var(--ol-bad); }
.ol-verdict[data-ok='unknown'] { color: var(--ol-muted); }
.ol-problems { margin: 8px 0 0; padding-left: 18px; color: var(--ol-bad); }
.ol-tamper { color: var(--ol-bad); font-weight: 500; }
.ol-event { display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; padding: 8px 0; border-top: 1px solid var(--ol-line); }
.ol-event:first-child { border-top: 0; }
.ol-event[data-flag='bad'] .ol-evtype { color: var(--ol-bad); }
.ol-event[data-flag='warn'] .ol-evtype { color: var(--ol-warn); }
.ol-event[data-flag='good'] .ol-evtype { color: var(--ol-good); }
.ol-evtype { font-weight: 600; }
.ol-track { position: relative; height: 12px; border-radius: 6px; background: var(--ol-surface); border: 1px solid var(--ol-line); margin: 10px 0 6px; }
.ol-band { position: absolute; top: 0; bottom: 0; background: color-mix(in srgb, var(--ol-accent) 30%, transparent); border-radius: 6px; }
.ol-mark { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--ol-fg); }
.ol-mark[data-kind='threshold'] { background: var(--ol-warn); }
.ol-progress { height: 8px; border-radius: 4px; background: var(--ol-surface); overflow: hidden; margin: 8px 0; }
.ol-progress > span { display: block; height: 100%; background: var(--ol-accent); }
.ol-progress[data-state='late'] > span, .ol-progress[data-state='bad'] > span { background: var(--ol-bad); }
.ol-progress[data-state='ok'] > span { background: var(--ol-good); }

/* Controls */
.ol-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.ol-chip, .ol-sortbtn, .ol-twist { font: inherit; color: inherit; background: transparent; border: 1px solid var(--ol-line); border-radius: 999px; padding: 2px 10px; cursor: pointer; }
.ol-chip[aria-pressed='true'] { background: var(--ol-accent); color: var(--ol-bg); border-color: var(--ol-accent); }
.ol-sortbtn { border: 0; padding: 0; font-weight: 600; border-radius: 4px; }
.ol-twist { border: 0; width: 18px; padding: 0; display: inline-block; text-align: center; }
.ol :is(.ol-chip, .ol-sortbtn, .ol-twist, select):focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
.ol select { font: inherit; color: inherit; background: var(--ol-bg); border: 1px solid var(--ol-line); border-radius: 6px; padding: 2px 6px; margin-left: 4px; }
.ol-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; padding: 0; }
.ol-scroll { overflow-x: auto; }

/* Table */
.ol-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.ol-table th, .ol-table td { text-align: left; padding: 6px 10px; border-top: 1px solid var(--ol-line); vertical-align: top; }
.ol-table thead th { border-top: 0; font-size: 12px; color: var(--ol-muted); }
.ol-table tbody th { font-weight: 500; }
.ol-table tfoot th, .ol-table tfoot td { border-top: 2px solid var(--ol-line); }
.ol-table td[data-pass='true'] { color: var(--ol-good); }
.ol-table td[data-pass='false'] { color: var(--ol-bad); background: color-mix(in srgb, var(--ol-bad) 8%, transparent); }
.ol-table tr[data-flip='regressed'] > th { box-shadow: inset 3px 0 var(--ol-bad); }
.ol-table tr[data-flip='improved'] > th { box-shadow: inset 3px 0 var(--ol-good); }
.ol-compare-bar { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 12px 0 8px; }

/* AgentTrace */

/* EvidenceDiff */
.ol [data-kind='add'] { background: color-mix(in srgb, var(--ol-good) 14%, transparent); }
.ol [data-kind='del'] { background: color-mix(in srgb, var(--ol-bad) 14%, transparent); }
.ol-word { color: inherit; border-radius: 2px; }
.ol-word[data-kind='add'] { background: color-mix(in srgb, var(--ol-good) 38%, transparent); }
.ol-word[data-kind='del'] { background: color-mix(in srgb, var(--ol-bad) 38%, transparent); }

/* ApprovalFlow */
.ol-flow-edge { fill: none; stroke: var(--ol-muted); stroke-width: 1.5; }
.ol-flow-arrow { fill: var(--ol-muted); }
.ol-flow-label { fill: var(--ol-muted); font: 11px system-ui, sans-serif; paint-order: stroke; stroke: var(--ol-bg); stroke-width: 4px; stroke-linejoin: round; }

/* ChainGraph */
.ol-chain { display: flex; align-items: stretch; padding: 4px 0 8px; }
.ol-block { flex: 0 0 204px; border: 1px solid var(--ol-line); border-radius: 8px; padding: 8px 10px; display: grid; gap: 2px; align-content: start; background: var(--ol-surface); }
.ol-block .ol-pill { white-space: nowrap; justify-self: start; margin-top: 4px; }
.ol-block[data-bad='true'] { border-color: var(--ol-bad); }
.ol-link { flex: 0 0 32px; align-self: center; height: 2px; background: var(--ol-good); position: relative; }
.ol-link[data-ok='false'] { background: repeating-linear-gradient(90deg, var(--ol-bad) 0 4px, transparent 4px 8px); }
.ol-link > span { position: absolute; top: -18px; left: 50%; transform: translateX(-50%); color: var(--ol-bad); font-weight: 700; }

/* Receipt */
.ol-receipt-foot { margin-top: 12px; padding-top: 10px; border-top: 1px dashed var(--ol-line); display: grid; gap: 8px; }
@media print { .ol { border-color: #999; break-inside: avoid; } }

/* Categorical palette, used by anything that colours by kind */
.ol { --ol-c1: #2563c7; --ol-c2: #a85a0a; --ol-c3: #1d7a56; --ol-c4: #7a4cc2; --ol-c5: #bf3557; --ol-c6: #17788a; --ol-c7: #7d6a0f; --ol-c8: #5b6470; --ol-on-c: #ffffff; font-variant-numeric: tabular-nums; }
.ol-num { text-align: right !important; }
.ol-ell { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.ol-dot-kind { display: inline-block; width: 9px; height: 9px; border-radius: 2px; flex: none; }
.ol-linkbtn { font: inherit; color: var(--ol-accent); background: none; border: 0; padding: 0; cursor: pointer; text-decoration: underline; text-underline-offset: 2px; }
.ol-input { font: inherit; color: inherit; background: var(--ol-bg); border: 1px solid var(--ol-line); border-radius: 8px; padding: 4px 10px; min-width: 160px; }
.ol-input:focus-visible, .ol-trace-body:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
.ol-chip:disabled { opacity: 0.45; cursor: default; }
.ol-tabs { display: inline-flex; background: var(--ol-surface); border-radius: 8px; padding: 2px; gap: 2px; }
.ol-tab { font: inherit; font-size: 13px; color: var(--ol-muted); background: transparent; border: 0; border-radius: 6px; padding: 3px 10px; cursor: pointer; }
.ol-tab[aria-selected='true'] { background: var(--ol-bg); color: var(--ol-fg); }
.ol-tab:disabled { opacity: 0.4; cursor: default; }
.ol-tab:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 1px; }
.ol-facts { display: flex; flex-wrap: wrap; gap: 6px 22px; margin: 4px 0 10px; }
.ol-facts > div { display: grid; }
.ol-facts dt { font-size: 12px; color: var(--ol-muted); }
.ol-facts dd { margin: 0; font-size: 16px; font-weight: 600; }
.ol-facts [data-bad='true'] dd { color: var(--ol-bad); }
.ol-facts [data-warn='true'] dd { color: var(--ol-warn); }
.ol-toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 8px; }
.ol-zoom { display: inline-flex; gap: 4px; }
.ol-legend { display: flex; flex-wrap: wrap; gap: 4px 6px; margin-bottom: 10px; }
.ol-legend-item { font: inherit; font-size: 12.5px; color: inherit; background: transparent; border: 1px solid var(--ol-line); border-radius: 8px; padding: 3px 9px; cursor: pointer; display: inline-flex; gap: 6px; align-items: center; }
.ol-legend-item i { width: 9px; height: 9px; border-radius: 2px; }
.ol-legend-item[aria-pressed='true'] { border-color: var(--ol-accent); background: color-mix(in srgb, var(--ol-accent) 10%, transparent); }
.ol-trace-body { position: relative; border: 1px solid var(--ol-line); border-radius: 10px; background: var(--ol-surface); overflow: hidden; outline-offset: 2px; }
.ol-mini { position: relative; height: 46px; background: var(--ol-bg); border-bottom: 1px solid var(--ol-line); cursor: crosshair; touch-action: none; }
.ol-mini-bar { position: absolute; border-radius: 1px; pointer-events: none; }
.ol-mini-shade { position: absolute; top: 0; bottom: 0; background: color-mix(in srgb, var(--ol-fg) 12%, transparent); pointer-events: none; }
.ol-brush { position: absolute; top: 0; bottom: 0; border: 1.5px solid var(--ol-accent); background: color-mix(in srgb, var(--ol-accent) 8%, transparent); cursor: grab; }
.ol-brush:active { cursor: grabbing; }
.ol-brush-h { position: absolute; top: 0; bottom: 0; width: 7px; cursor: ew-resize; background: var(--ol-accent); opacity: 0.55; border-radius: 2px; }
.ol-ruler { position: relative; height: 22px; border-bottom: 1px solid var(--ol-line); background: var(--ol-bg); font-size: 11px; color: var(--ol-muted); overflow: hidden; }
.ol-ruler span { position: absolute; top: 4px; transform: translateX(4px); white-space: nowrap; }
.ol-ruler span::before { content: ''; position: absolute; left: -4px; top: -4px; height: 22px; width: 1px; background: var(--ol-line); }
.ol-gridline { position: absolute; top: 0; bottom: 0; width: 1px; background: color-mix(in srgb, var(--ol-fg) 8%, transparent); pointer-events: none; }
.ol-flame { position: relative; margin: 4px 0; }
.ol-bar-span { position: absolute; border-radius: 3px; color: var(--ol-on-c); font-size: 11.5px; line-height: 19px; padding: 0 5px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; cursor: pointer; }
.ol-bar-span > span { display: block; overflow: hidden; text-overflow: ellipsis; }
.ol-bar-span:hover { filter: brightness(1.12); }
.ol-bar-span[data-dim='true'], .ol-wrow[data-dim='true'] { opacity: 0.22; }
.ol-bar-span[data-status='error'] { background-image: repeating-linear-gradient(135deg, rgb(255 255 255 / 0.28) 0 3px, transparent 3px 7px) !important; outline: 1.5px solid var(--ol-bad); outline-offset: -1.5px; }
.ol-bar-span[data-status='blocked'] { outline: 1.5px dashed var(--ol-warn); outline-offset: -1.5px; }
.ol-bar-span[data-critical='true'] { outline: 2px solid var(--ol-fg); outline-offset: 0; z-index: 1; }
.ol-bar-span[data-selected='true'] { outline: 2px solid var(--ol-accent); outline-offset: 2px; z-index: 2; }
.ol-wfall { padding: 4px 0; max-height: 380px; overflow: auto; }
.ol-wrow { display: grid; grid-template-columns: minmax(150px, 30%) 1fr; align-items: center; min-height: 26px; cursor: pointer; }
.ol-wrow:hover, .ol-wrow[data-selected='true'] { background: color-mix(in srgb, var(--ol-accent) 9%, transparent); }
.ol-wname { display: flex; align-items: center; gap: 6px; padding-right: 8px; min-width: 0; }
.ol-wtrack { position: relative; height: 18px; }
.ol-wbar { position: absolute; top: 3px; height: 12px; border-radius: 3px; }
.ol-wbar[data-status='error'] { outline: 1.5px solid var(--ol-bad); background-image: repeating-linear-gradient(135deg, rgb(255 255 255 / 0.3) 0 3px, transparent 3px 7px) !important; }
.ol-wbar[data-status='blocked'] { outline: 1.5px dashed var(--ol-warn); }
.ol-wbar[data-critical='true'] { outline: 2px solid var(--ol-fg); }
.ol-wlabel { position: absolute; top: 1px; font-size: 11px; color: var(--ol-muted); white-space: nowrap; }
.ol-list-table tbody tr { cursor: pointer; }
.ol-list-table tbody tr:hover, .ol-list-table tbody tr[data-selected='true'] { background: color-mix(in srgb, var(--ol-accent) 9%, transparent); }
.ol-share { display: inline-block; width: 90px; height: 7px; border-radius: 4px; background: var(--ol-line); vertical-align: middle; overflow: hidden; }
.ol-share > span { display: block; height: 100%; border-radius: 4px; }
.ol-tip { position: absolute; z-index: 5; pointer-events: none; min-width: 190px; background: var(--ol-bg); color: var(--ol-fg); border: 1px solid var(--ol-line); border-radius: 8px; padding: 8px 10px; box-shadow: 0 6px 20px color-mix(in srgb, var(--ol-fg) 18%, transparent); font-size: 12.5px; }
.ol-detail { margin-top: 12px; border-top: 1px solid var(--ol-line); padding-top: 10px; }
.ol-io { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; }

/* JsonTree */
.ol-json { font: 12.5px/1.6 var(--ol-mono); background: var(--ol-bg); border: 1px solid var(--ol-line); border-radius: 8px; padding: 6px 8px; overflow: auto; max-height: 260px; }
.ol-json-row { display: flex; align-items: baseline; gap: 2px; white-space: nowrap; }
.ol-json-twist { background: none; border: 0; color: var(--ol-muted); width: 16px; padding: 0; font: inherit; cursor: pointer; flex: none; }
.ol-json-key { background: none; border: 0; padding: 0; font: inherit; color: var(--ol-c4); cursor: pointer; }
.ol-json-key:hover { text-decoration: underline; }
.ol-json-colon, .ol-json-punct { color: var(--ol-muted); }
.ol-json-summary { color: var(--ol-muted); font-style: italic; }
.ol-json-copied { color: var(--ol-good); font-size: 11px; }
.ol-json-val[data-kind='string'] { color: var(--ol-c3); white-space: pre-wrap; word-break: break-word; }
.ol-json-val[data-kind='number'] { color: var(--ol-c2); }
.ol-json-val[data-kind='boolean'] { color: var(--ol-c1); }
.ol-json-val[data-kind='null'], .ol-json-val[data-kind='other'] { color: var(--ol-muted); }
.ol-json-more { background: none; border: 0; color: var(--ol-accent); font: inherit; font-size: 11.5px; cursor: pointer; margin-left: 8px; text-decoration: underline; }

/* DiffViewer */
.ol-add { color: var(--ol-good); font-weight: 600; }
.ol-del { color: var(--ol-bad); font-weight: 600; }
.ol-spacer { flex: 1; }
.ol-statbar { display: inline-flex; gap: 2px; vertical-align: middle; margin-left: 4px; }
.ol-statbar i { width: 8px; height: 8px; border-radius: 1px; background: var(--ol-line); }
.ol-statbar i[data-k='add'] { background: var(--ol-good); }
.ol-statbar i[data-k='del'] { background: var(--ol-bad); }
.ol-diffv-body { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; margin-top: 10px; align-items: start; }
.ol-diffv-body:not(:has(.ol-ftree)) { grid-template-columns: minmax(0, 1fr); }
.ol-ftree { display: grid; gap: 2px; width: 230px; align-content: start; position: sticky; top: 8px; font-size: 13px; }
.ol-ftree a { display: flex; justify-content: space-between; gap: 8px; padding: 5px 8px; border-radius: 6px; color: inherit; text-decoration: none; }
.ol-ftree a:hover { background: var(--ol-surface); }
.ol-ftree a:focus-visible { outline: 2px solid var(--ol-accent); }
.ol-fcount { font-size: 12px; white-space: nowrap; flex: none; }
.ol-ftree a > .ol-ell { min-width: 0; flex: 1; }
.ol-c-ln { width: 46px; }
.ol-c-sign { width: 18px; }
.ol-files { display: grid; gap: 12px; min-width: 0; }
.ol-file { border: 1px solid var(--ol-line); border-radius: 8px; overflow: hidden; }
.ol-file-head { display: flex; align-items: center; gap: 8px; padding: 6px 10px; background: var(--ol-surface); font-size: 13px; }
.ol-viewed { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; color: var(--ol-muted); cursor: pointer; }
.ol-dtable { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 12.5px; }
.ol-dtable[data-mode='split'] .ol-ln { width: 42px; }
.ol-dtable[data-mode='split'] .ol-sign { width: 16px; }
.ol-dtable[data-mode='unified'] .ol-ln { width: 46px; }
.ol-dtable[data-mode='unified'] .ol-sign { width: 18px; }
.ol-ln { text-align: right; padding: 0 8px; color: var(--ol-muted); user-select: none; cursor: pointer; font: 12px/1.6 var(--ol-mono); vertical-align: top; background: color-mix(in srgb, var(--ol-fg) 3%, transparent); }
.ol-ln[data-active='true'] { color: var(--ol-fg); background: color-mix(in srgb, var(--ol-warn) 28%, transparent); }
.ol-sign { text-align: center; color: var(--ol-muted); vertical-align: top; font: 12px/1.6 var(--ol-mono); }
.ol-sign[data-kind='add'], .ol-code[data-kind='add'] { background: color-mix(in srgb, var(--ol-good) 14%, transparent); }
.ol-sign[data-kind='del'], .ol-code[data-kind='del'] { background: color-mix(in srgb, var(--ol-bad) 14%, transparent); }
.ol-code { padding: 0 8px; white-space: pre-wrap; word-break: break-word; line-height: 1.6; vertical-align: top; }
.ol-code[data-kind='empty'] { background: color-mix(in srgb, var(--ol-fg) 4%, transparent); }
.ol-code[data-active='true'] { box-shadow: inset 3px 0 var(--ol-warn); }
.ol-dtable[data-mode='split'] td:nth-child(3) { border-right: 1px solid var(--ol-line); }
.ol-hunk td { background: color-mix(in srgb, var(--ol-c1) 12%, transparent); color: var(--ol-muted); padding: 2px 10px; font-size: 12px; }
.ol-gap td { background: color-mix(in srgb, var(--ol-c1) 7%, transparent); padding: 0; }
.ol-gap button { font: inherit; font-size: 12px; color: var(--ol-muted); background: none; border: 0; width: 100%; text-align: left; padding: 4px 12px; cursor: pointer; }
.ol-gap button:hover { color: var(--ol-fg); background: color-mix(in srgb, var(--ol-c1) 14%, transparent); }
.ol-comment-row td { padding: 6px 12px 8px 60px; background: var(--ol-surface); }
.ol-comment { border: 1px solid var(--ol-line); border-radius: 8px; padding: 8px 10px; background: var(--ol-bg); font-size: 13px; max-width: 560px; }

/* FlowCanvas */
.ol-legendrow { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 12px; color: var(--ol-muted); }
.ol-ldot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-left: 6px; background: var(--ol-line); }
.ol-legendrow .ol-ldot { margin: 0 4px 0 0; }
.ol-ldot[data-s='done'] { background: var(--ol-good); }
.ol-ldot[data-s='active'] { background: var(--ol-c1); }
.ol-ldot[data-s='blocked'] { background: var(--ol-bad); }
.ol-canvas { position: relative; margin-top: 10px; border: 1px solid var(--ol-line); border-radius: 10px; overflow: hidden; background: var(--ol-surface); cursor: grab; touch-action: none; user-select: none; }
.ol-canvas:active { cursor: grabbing; }
.ol-canvas:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
.ol-dots { position: absolute; inset: 0; pointer-events: none; }
.ol-dot-fill { fill: color-mix(in srgb, var(--ol-fg) 20%, transparent); }
.ol-world { position: absolute; left: 0; top: 0; transform-origin: 0 0; will-change: transform; }
.ol-laneband { position: absolute; border-block: 1px solid var(--ol-line); background: color-mix(in srgb, var(--ol-fg) 3%, transparent); pointer-events: none; }
.ol-laneband[data-odd='1'] { background: transparent; }
.ol-laneband span { position: absolute; left: 8px; top: 5px; font-size: 12px; font-weight: 500; color: var(--ol-muted); }
.ol-edges { position: absolute; left: 0; pointer-events: none; }
.ol-edges g[data-on='false'] { opacity: 0.14; }
.ol-edges .ol-flow-edge { stroke-width: 1.6; }
.ol-edges g[data-animated='true'] .ol-flow-edge { stroke: var(--ol-c1); stroke-dasharray: 6 5; animation: ol-dash 0.9s linear infinite; }
@keyframes ol-dash { to { stroke-dashoffset: -11; } }
@media (prefers-reduced-motion: reduce) { .ol-edges g[data-animated='true'] .ol-flow-edge { animation: none; } }
.ol-edge-pill { fill: var(--ol-bg); stroke: var(--ol-line); }
.ol-fnode { position: absolute; font: inherit; color: inherit; text-align: left; background: var(--ol-bg); border: 1.5px solid var(--ol-line); border-radius: 10px; padding: 7px 12px; display: grid; align-content: center; gap: 1px; cursor: pointer; transition: opacity 0.15s; }
.ol-fnode:hover { border-color: var(--ol-muted); }
.ol-fnode:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
.ol-fnode[data-kind='gate'] { border-style: dashed; border-color: var(--ol-warn); border-radius: 22px; }
.ol-fnode[data-kind='end'] { border-radius: 29px; }
.ol-fnode[data-kind='start'] { border-radius: 29px; border-color: var(--ol-c3); }
.ol-fnode[data-status='done'] { border-color: var(--ol-good); }
.ol-fnode[data-status='active'] { border-color: var(--ol-c1); background: color-mix(in srgb, var(--ol-c1) 8%, var(--ol-bg)); }
.ol-fnode[data-status='blocked'] { border-color: var(--ol-bad); background: color-mix(in srgb, var(--ol-bad) 7%, var(--ol-bg)); }
.ol-fnode[data-selected='true'] { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
.ol-fnode[data-dim='true'] { opacity: 0.35; }
.ol-fkind { font-size: 11.5px; color: var(--ol-muted); display: flex; align-items: center; justify-content: space-between; }
.ol-flabel { font-weight: 600; font-size: 13.5px; line-height: 1.25; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ol-handle { position: absolute; top: 50%; width: 9px; height: 9px; margin-top: -4.5px; border-radius: 50%; background: var(--ol-bg); border: 1.5px solid var(--ol-muted); }
.ol-handle[data-side='l'] { left: -5px; } .ol-handle[data-side='r'] { right: -5px; }
.ol-fctl { position: absolute; left: 10px; bottom: 10px; display: flex; border: 1px solid var(--ol-line); border-radius: 8px; overflow: hidden; background: var(--ol-bg); }
.ol-fctl button { font: inherit; width: 30px; height: 30px; background: none; border: 0; border-left: 1px solid var(--ol-line); color: inherit; cursor: pointer; }
.ol-fctl button:first-child { border-left: 0; }
.ol-fctl button:hover, .ol-fctl button[aria-pressed='true'] { background: var(--ol-surface); }
.ol-minimap { position: absolute; right: 10px; bottom: 10px; background: var(--ol-bg); border: 1px solid var(--ol-line); border-radius: 8px; cursor: pointer; }
.ol-mm-node { fill: var(--ol-muted); opacity: 0.5; }
.ol-mm-node[data-status='done'] { fill: var(--ol-good); opacity: 0.8; } .ol-mm-node[data-status='active'] { fill: var(--ol-c1); opacity: 0.9; } .ol-mm-node[data-status='blocked'] { fill: var(--ol-bad); opacity: 0.9; }
.ol-mm-view { fill: color-mix(in srgb, var(--ol-accent) 10%, transparent); stroke: var(--ol-accent); stroke-width: 1.2; }
.ol-fdetail { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 16px; }
.ol-fdetail .ol-linkbtn { display: block; text-align: left; margin-top: 2px; }
@media (max-width: 640px) { .ol-fdetail { grid-template-columns: 1fr; } }

/* DataGrid */
.ol-dg { position: relative; overflow: auto; border: 1px solid var(--ol-line); border-radius: 10px; background: var(--ol-bg); margin-top: 10px; outline-offset: 2px; }
.ol-dg:focus-visible { outline: 2px solid var(--ol-accent); }
.ol-ghead { position: sticky; top: 0; z-index: 4; display: grid; background: var(--ol-surface); border-bottom: 1px solid var(--ol-line); font-size: 12.5px; }
.ol-gfilters { z-index: 3; }
.ol-gcell { display: flex; align-items: center; padding: 0 10px; min-width: 0; overflow: hidden; background: inherit; }
.ol-gcell[data-align='right'] { justify-content: flex-end; text-align: right; }
.ol-ghcell { position: relative; font-weight: 600; color: var(--ol-muted); }
.ol-ghcell .ol-sortbtn { font: inherit; font-weight: 600; color: inherit; }
.ol-ghcell .ol-sortbtn:hover { color: var(--ol-fg); }
.ol-ghcell sup { font-size: 11px; margin-left: 1px; }
.ol-resize { position: absolute; right: 0; top: 6px; bottom: 6px; width: 7px; cursor: col-resize; border-right: 1px solid var(--ol-line); touch-action: none; }
.ol-resize:hover { border-right: 2px solid var(--ol-accent); }
.ol-gcheck { justify-content: center; padding: 0; background: var(--ol-surface); }
.ol-gbody { position: relative; }
.ol-grow { position: absolute; left: 0; display: grid; align-items: stretch; border-bottom: 1px solid color-mix(in srgb, var(--ol-line) 60%, transparent); background: var(--ol-bg); font-size: 13px; }
.ol-grow .ol-gcheck { background: var(--ol-bg); }
.ol-grow:hover, .ol-grow:hover .ol-gcheck { background: var(--ol-surface); }
.ol-grow[data-selected='true'], .ol-grow[data-selected='true'] .ol-gcheck { background: color-mix(in srgb, var(--ol-accent) 11%, var(--ol-bg)); }
.ol-grow[data-active='true'] { box-shadow: inset 2px 0 var(--ol-accent); }
.ol-dg:not(:focus-visible) .ol-grow[data-active='true'] { box-shadow: none; }
.ol-gfilters .ol-gcell { background: var(--ol-surface); }
.ol-finput { width: 100%; padding: 2px 6px; min-width: 0; font-size: 12px; }
.ol-finput[data-bad='true'] { border-color: var(--ol-bad); }
.ol-pctcell { display: inline-flex; align-items: center; gap: 8px; width: 100%; justify-content: flex-end; }
.ol-pctbar { width: 54px; height: 6px; border-radius: 3px; background: var(--ol-line); overflow: hidden; }
.ol-pctbar > span { display: block; height: 100%; background: var(--ol-c3); }
.ol-spark polyline { stroke: var(--ol-c1); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
.ol-spark circle { fill: var(--ol-c1); }
.ol-selbar { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 6px 12px; border-radius: 8px; background: color-mix(in srgb, var(--ol-accent) 10%, var(--ol-bg)); font-size: 13px; }
.ol-gempty { position: sticky; left: 24px; padding: 40px 0; display: grid; justify-items: start; gap: 6px; }
.ol-gfoot { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 18px; margin-top: 8px; font-size: 12.5px; }

/* Charts */
.ol-spc, .ol-sankey { position: relative; margin-top: 8px; }
.ol-spc svg, .ol-sankey svg { display: block; overflow: visible; }
.ol-axis-line { stroke: color-mix(in srgb, var(--ol-fg) 9%, transparent); }
.ol-axis-text { fill: var(--ol-muted); font: 11px system-ui, sans-serif; }
.ol-zone3 { fill: color-mix(in srgb, var(--ol-c1) 6%, transparent); }
.ol-zone2 { fill: color-mix(in srgb, var(--ol-c1) 7%, transparent); }
.ol-zone1 { fill: color-mix(in srgb, var(--ol-c3) 11%, transparent); }
.ol-limit { stroke: var(--ol-bad); stroke-width: 1.2; stroke-dasharray: 4 3; opacity: 0.8; }
.ol-center { stroke: var(--ol-fg); stroke-width: 1.3; opacity: 0.55; }
.ol-baseline { fill: color-mix(in srgb, var(--ol-fg) 5%, transparent); }
.ol-marker { stroke: var(--ol-muted); stroke-width: 1; stroke-dasharray: 2 3; }
.ol-series { stroke: var(--ol-c1); stroke-width: 1.6; stroke-linejoin: round; }
.ol-pt { fill: var(--ol-bg); stroke: var(--ol-c1); stroke-width: 1.6; }
.ol-pt[data-signal='true'] { fill: var(--ol-bad); stroke: var(--ol-bg); stroke-width: 1.5; }
.ol-pt[data-hover='true'] { stroke-width: 3; }
.ol-rule { fill: var(--ol-bad); font: 700 11px system-ui, sans-serif; }
.ol-cross { stroke: var(--ol-fg); stroke-width: 1; opacity: 0.3; }
.ol-slink { opacity: 0.32; transition: opacity 0.12s; mix-blend-mode: normal; }
.ol-slink[data-active='false'] { opacity: 0.06; }
.ol-slink:hover { opacity: 0.6; }
.ol-snode { opacity: 0.9; }
.ol-slabel { fill: var(--ol-fg); font: 600 12.5px system-ui, sans-serif; }
.ol g[data-leak='true'] .ol-slabel { fill: var(--ol-bad); }

/* ApprovalQueue */
.ol-queue-body { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; margin-top: 12px; align-items: start; outline-offset: 4px; border-radius: 10px; }
.ol-queue-body:focus-visible { outline: 2px solid var(--ol-accent); }
.ol-qlist { display: grid; gap: 4px; }
.ol-qitem { display: grid; grid-template-columns: 8px minmax(0, 1fr); gap: 10px; align-items: stretch; padding: 8px 10px; border: 1px solid var(--ol-line); border-radius: 10px; cursor: pointer; background: var(--ol-bg); }
.ol-qitem:hover { background: var(--ol-surface); }
.ol-qitem[data-selected='true'] { border-color: var(--ol-accent); outline: 1px solid var(--ol-accent); }
.ol-qmain { min-width: 0; display: grid; justify-items: start; }
.ol-qtitle { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.3; }
.ol-risk { width: 8px; min-height: 30px; border-radius: 4px; background: var(--ol-good); }
.ol-risk[data-risk='medium'] { background: var(--ol-warn); } .ol-risk[data-risk='high'] { background: var(--ol-bad); }
.ol-qdetail { border: 1px solid var(--ol-line); border-radius: 10px; padding: 14px; min-width: 0; }
.ol-statusline { margin: 4px 0 10px; padding: 6px 10px; border-radius: 8px; background: var(--ol-surface); font-size: 13px; }
.ol-statusline[data-status='stale'], .ol-statusline[data-status='expired'], .ol-statusline[data-status='rejected'] { background: color-mix(in srgb, var(--ol-bad) 10%, var(--ol-bg)); color: var(--ol-bad); }
.ol-statusline[data-status='approved'] { background: color-mix(in srgb, var(--ol-good) 10%, var(--ol-bg)); color: var(--ol-good); }
.ol-qgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.ol-qhead { font-size: 12.5px; font-weight: 500; color: var(--ol-muted); margin-bottom: 4px; }
.ol-evidence { display: grid; gap: 4px; font-size: 13px; }
.ol-evidence li { display: grid; grid-template-columns: 18px 1fr; gap: 4px; }
.ol-evidence li[data-ok='true'] > span:first-child { color: var(--ol-good); } .ol-evidence li[data-ok='false'] > span:first-child { color: var(--ol-bad); font-weight: 700; }
.ol-dlog { display: grid; gap: 3px; font-size: 13px; }
.ol-dlog li[data-ignored='true'] { opacity: 0.7; } .ol-ignored { color: var(--ol-bad); }
.ol-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.ol-btn { font: inherit; font-weight: 600; font-size: 13px; padding: 8px 14px; border-radius: 8px; border: 1px solid var(--ol-line); background: var(--ol-bg); color: var(--ol-fg); cursor: pointer; }
.ol-btn:hover:not(:disabled) { background: var(--ol-surface); }
.ol-btn[data-kind='approve'] { background: var(--ol-accent); color: var(--ol-bg); border-color: var(--ol-accent); }
.ol-btn[data-kind='reject'] { color: var(--ol-bad); border-color: currentColor; }
.ol-btn:disabled { opacity: 0.42; cursor: not-allowed; }
.ol-btn:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
@media (max-width: 760px) { .ol-queue-body { grid-template-columns: 1fr; } }

/* DeadlineGantt */
.ol-gantt { position: relative; margin-top: 8px; overflow-x: auto; }
.ol-gantt svg { display: block; }
.ol-gbar { fill: var(--ol-c1); }
.ol-gbar[data-state='met'] { fill: var(--ol-good); } .ol-gbar[data-state='late'], .ol-gbar[data-state='overdue'] { fill: var(--ol-c1); } .ol-gbar[data-state='remedied'] { fill: var(--ol-warn); }
.ol-gover { fill: url(#olx-hatch); stroke: var(--ol-bad); stroke-width: 1; }
.ol-hatch-bg { fill: color-mix(in srgb, var(--ol-bad) 14%, var(--ol-bg)); } .ol-hatch-line { stroke: var(--ol-bad); stroke-width: 2; }
.ol-diamond { fill: var(--ol-bg); stroke: var(--ol-fg); stroke-width: 1.6; }
.ol-diamond[data-state='overdue'], .ol-diamond[data-state='late'] { stroke: var(--ol-bad); fill: var(--ol-bad); }
.ol-diamond[data-state='met'] { stroke: var(--ol-good); }
.ol-now { stroke: var(--ol-c1); stroke-width: 1.4; stroke-dasharray: 3 3; }
.ol-now-text { fill: var(--ol-c1); font: 700 11px system-ui, sans-serif; }

/* ActivityHeatmap */
.ol-hcell { fill: color-mix(in srgb, var(--ol-fg) 8%, transparent); }
.ol-hcell[data-level='1'], .ol-hcell-sw[data-level='1'] { fill: color-mix(in srgb, var(--ol-c3) 28%, transparent); background: color-mix(in srgb, var(--ol-c3) 28%, transparent); }
.ol-hcell[data-level='2'], .ol-hcell-sw[data-level='2'] { fill: color-mix(in srgb, var(--ol-c3) 50%, transparent); background: color-mix(in srgb, var(--ol-c3) 50%, transparent); }
.ol-hcell[data-level='3'], .ol-hcell-sw[data-level='3'] { fill: color-mix(in srgb, var(--ol-c3) 75%, transparent); background: color-mix(in srgb, var(--ol-c3) 75%, transparent); }
.ol-hcell[data-level='4'], .ol-hcell-sw[data-level='4'] { fill: var(--ol-c3); background: var(--ol-c3); }
.ol-hcell[data-hover='true'] { stroke: var(--ol-fg); stroke-width: 1.5; }
.ol-hbreach { fill: var(--ol-bad); stroke: var(--ol-bg); stroke-width: 1; }
.ol-hlegend { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--ol-muted); margin-top: 6px; }
.ol-hcell-sw { display: inline-block; width: 13px; height: 13px; border-radius: 3px; background: color-mix(in srgb, var(--ol-fg) 8%, transparent); }
.ol-hbreach-sw { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--ol-bad); }

.ol-axis-text[data-day='true'] { fill: var(--ol-fg); font-weight: 700; }
.ol-hatch-sw { display: inline-block; width: 16px; height: 10px; border-radius: 2px; border: 1px solid var(--ol-bad); background: repeating-linear-gradient(135deg, var(--ol-bad) 0 2px, transparent 2px 5px); }
.ol-now-sw { display: inline-block; width: 0; height: 12px; border-left: 2px dashed var(--ol-c1); }
.ol-hlegend svg { display: inline-block; }

/* Marks and folds */
.ol-icon { display: inline-block; vertical-align: -2px; flex: none; }
.ol-statement { margin: 4px 0 8px; font-weight: 600; font-size: 15px; line-height: 1.4; }
.ol-remedy { margin: 0 0 6px; }
.ol-fold { margin-top: 6px; font-size: 13px; }
.ol-fold summary { cursor: pointer; color: var(--ol-muted); width: fit-content; }
.ol-fold summary:hover { color: var(--ol-fg); }
.ol-fold p { margin: 6px 0 0; color: var(--ol-muted); }
.ol-verdict svg { width: 18px; height: 18px; }
.ol-cellmark svg { width: 15px; height: 15px; }
.ol-link > span svg { width: 13px; height: 13px; }
.ol-minimap { box-shadow: none; }

/* Figures as type, and key hints on the buttons they belong to */
.ol-figs { display: flex; flex-wrap: wrap; gap: 4px 28px; margin: 0; }
.ol-figs > div { display: flex; flex-direction: column-reverse; }
.ol-figs dd { margin: 0; font-size: 22px; font-weight: 600; line-height: 1.15; }
.ol-figs dt { font-size: 12px; color: var(--ol-muted); }
.ol-figs > div[data-bad='true'] dd { color: var(--ol-bad); }
.ol-bigfig { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; margin: 2px 0 2px; }
.ol-bigfig b { font-size: 26px; font-weight: 600; line-height: 1.1; }
kbd { font: inherit; font-size: 11px; margin-left: 8px; padding: 0 5px; border-radius: 4px; background: color-mix(in srgb, currentColor 14%, transparent); }
.ol-chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }

/* Narrow screens: the hash chain stacks instead of scrolling sideways */
@media (max-width: 640px) {
  .ol-chain { flex-direction: column; align-items: stretch; }
  .ol-block { flex: none; }
  .ol-link { flex: none; width: 2px; height: 22px; align-self: center; }
  .ol-link[data-ok='false'] { background: repeating-linear-gradient(180deg, var(--ol-bad) 0 4px, transparent 4px 8px); }
  .ol-link > span { top: 50%; left: 14px; transform: translateY(-50%); }
}

/* Judgements: AutonomyGate, EvidenceTable, PlanVsActual */
.ol-ladder { list-style: none; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 4px; margin: 4px 0 10px; padding: 0; }
.ol-ladder li { display: grid; gap: 1px; padding: 6px 8px; border-radius: 8px; background: var(--ol-surface); color: var(--ol-muted); font-size: 12.5px; min-width: 0; }
.ol-ladder li b { color: var(--ol-fg); font-weight: 600; }
.ol-ladder li[data-state='current'] { background: var(--ol-accent); color: var(--ol-bg); }
.ol-ladder li[data-state='current'] b { color: var(--ol-bg); }
.ol-ladder li[data-state='target'] { outline: 1.5px solid var(--ol-accent); outline-offset: -1.5px; color: var(--ol-fg); }
.ol-gatelist { margin-top: 10px; }
.ol-gatelist p { margin: 0 0 4px; }
.ol-gatelist ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 3px; }
.ol-gatelist li { display: flex; justify-content: space-between; gap: 12px; padding: 5px 10px; border-radius: 8px; background: var(--ol-surface); }
.ol-evlist { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 4px; }
.ol-evrow { border-radius: 8px; background: var(--ol-surface); }
.ol-evbtn { display: grid; grid-template-columns: minmax(80px, 0.35fr) minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; text-align: left; font: inherit; color: inherit; background: transparent; border: 0; border-radius: 8px; padding: 8px 10px; cursor: pointer; }
.ol-evbtn:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 1px; }
.ol-evfield { color: var(--ol-muted); }
.ol-evval { font-weight: 500; overflow-wrap: anywhere; }
.ol-evsrcs { list-style: none; margin: 0; padding: 0 10px 10px; display: grid; gap: 8px; }
.ol-evsrc { display: grid; gap: 3px; }
.ol-evread { font-size: 12.5px; color: var(--ol-muted); }
.ol-evbad { color: var(--ol-bad); font-weight: 500; }
.ol-excerpt { margin: 0; padding: 5px 8px; border-radius: 6px; background: var(--ol-bg); font-size: 12.5px; overflow-wrap: anywhere; }
.ol-pva { list-style: none; margin: 6px 0 0; padding: 0; display: grid; gap: 4px; }
.ol-pvarow { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); gap: 12px; align-items: center; padding: 7px 10px; border-radius: 8px; background: var(--ol-surface); }
.ol-pvaact { text-align: right; min-width: 0; overflow-wrap: anywhere; }
.ol-pvarow[data-state='skipped'] .ol-pvaact { color: var(--ol-muted); }
@media (max-width: 520px) {
  .ol-pvarow { grid-template-columns: minmax(0, 1fr); gap: 4px; }
  .ol-pvaact { text-align: left; }
  .ol-evbtn { grid-template-columns: minmax(0, 1fr) auto; }
  .ol-evfield { grid-column: 1 / -1; }
  .ol-ladder li span { display: none; }
}

/* Workspaces: RunInspector. Components inside a workspace share its frame instead of drawing their own. */
.ol .ol { border-width: 0; padding: 0; background: transparent; }
.ol-runfacts { list-style: none; margin: 6px 0 12px; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 6px; }
.ol-runfact { display: grid; align-content: start; gap: 3px; width: 100%; height: 100%; text-align: left; font: inherit; color: inherit; background: var(--ol-surface); border: 0; border-radius: 10px; padding: 10px 12px; cursor: pointer; }
.ol-runfact[data-tone='good'] { background: color-mix(in srgb, var(--ol-good) 11%, var(--ol-bg)); }
.ol-runfact[data-tone='warn'] { background: color-mix(in srgb, var(--ol-warn) 12%, var(--ol-bg)); }
.ol-runfact[data-tone='bad'] { background: color-mix(in srgb, var(--ol-bad) 11%, var(--ol-bg)); }
.ol-runfact:focus-visible { outline: 2px solid var(--ol-accent); outline-offset: 2px; }
.ol-runpanel { margin-top: 12px; }

/* ApprovalChain, HandoffPacket, ApprovalWorkspace */
.ol-achain { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.ol-astep { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px 10px; border-radius: 8px; background: var(--ol-surface); }
.ol-astep[data-status='upcoming'], .ol-astep[data-status='skipped'] { opacity: 0.6; }
.ol-aknob { display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--ol-bg); color: var(--ol-muted); font-size: 12px; font-weight: 600; }
.ol-astep[data-status='approved'] .ol-aknob { background: var(--ol-good); color: var(--ol-bg); }
.ol-astep[data-status='waiting'] .ol-aknob { background: var(--ol-accent); color: var(--ol-bg); }
.ol-astep[data-status='overdue'] .ol-aknob, .ol-astep[data-status='rejected'] .ol-aknob, .ol-astep[data-status='invalid'] .ol-aknob { background: var(--ol-bad); color: var(--ol-bg); }
.ol-abody { display: grid; gap: 1px; min-width: 0; }
.ol-achainwhy { color: var(--ol-bad); font-size: 12.5px; }
.ol-hand { display: grid; grid-template-columns: 78px minmax(0, 1fr); gap: 8px 12px; margin: 0; }
.ol-hand dt { color: var(--ol-muted); }
.ol-hand dd { margin: 0; overflow-wrap: anywhere; }
.ol-hand ul { margin: 0; padding-left: 18px; }
.ol-gap-note { display: inline-block; padding: 1px 8px; border-radius: 6px; background: color-mix(in srgb, var(--ol-warn) 14%, var(--ol-bg)); color: var(--ol-warn); font-size: 12.5px; }
.ol-work { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(280px, 1fr); gap: 16px; align-items: start; }
.ol-workside { display: grid; gap: 10px; }
@media (max-width: 900px) { .ol-work { grid-template-columns: minmax(0, 1fr); } }

/* permission grants and budget meter */
.ol-meter { display: block; height: 6px; border-radius: 999px; background: var(--ol-surface); overflow: hidden; }
.ol-meter-fill { display: block; height: 100%; border-radius: 999px; background: var(--ol-accent); }
.ol-meter-fill[data-tone='warn'] { background: var(--ol-warn); }
.ol-meter-fill[data-tone='bad'] { background: var(--ol-bad); }
.ol-grants { list-style: none; margin: 6px 0 0; padding: 0; display: grid; gap: 4px; }
.ol-grant { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 12px; align-items: center; padding: 9px 10px; border-radius: 8px; background: var(--ol-surface); }
.ol-grant[data-status='expired'], .ol-grant[data-status='revoked'] { opacity: 0.7; }
.ol-grant-by { display: block; }
.ol-grant-use { grid-column: 1 / -1; display: grid; gap: 4px; }
.ol-grant-why { grid-column: 1 / -1; margin: 0; }
.ol-budget-fig { margin: 4px 0 8px; }
.ol-budget-used { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
.ol-budget-track { position: relative; padding: 4px 0; }
.ol-budget-mark { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px; border-radius: 1px; background: var(--ol-fg); }
.ol-budget-facts { display: flex; flex-wrap: wrap; gap: 4px 20px; margin: 10px 0 0; }
.ol-budget-facts div { display: grid; }
.ol-budget-facts dt { color: var(--ol-muted); font-size: 12px; }
.ol-budget-facts dd { margin: 0; font-variant-numeric: tabular-nums; }
.ol-grant-main { min-width: 0; overflow-wrap: anywhere; }

/* autonomy board */
.ol-fleetlist { list-style: none; margin: 6px 0 0; padding: 0; display: grid; gap: 4px; }
.ol-fleetrow { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.2fr) minmax(0, 1.6fr); gap: 8px 16px; align-items: center; padding: 10px 12px; border-radius: 8px; background: var(--ol-surface); }
.ol-fleetrow[data-flag='bad'] { background: color-mix(in srgb, var(--ol-bad) 7%, var(--ol-bg)); }
.ol-fleetrow[data-flag='warn'] { background: color-mix(in srgb, var(--ol-warn) 8%, var(--ol-bg)); }
.ol-fleetname, .ol-fleetgate { display: grid; gap: 3px; justify-items: start; min-width: 0; }
.ol-fleetnote { display: flex; flex-wrap: wrap; gap: 4px; min-width: 0; }
.ol-fleetnote .ol-pill { white-space: normal; }
@media (max-width: 640px) { .ol-fleetrow { grid-template-columns: minmax(0, 1fr); } }
